CREATE TYPE "Role" AS ENUM ('USER','ADMIN');
CREATE TYPE "MonitorStatus" AS ENUM ('ACTIVE','PAUSED','ERROR');
CREATE TYPE "Availability" AS ENUM ('AVAILABLE','UNAVAILABLE','REMOVED');
CREATE TYPE "Confidence" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE "AlertSeverity" AS ENUM ('INFO','WARNING','CRITICAL');
CREATE TYPE "JobStatus" AS ENUM ('PENDING','RUNNING','COMPLETED','FAILED');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'USER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Competitor" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "name" TEXT NOT NULL, "username" TEXT, "shopUrl" TEXT NOT NULL, "profileUrl" TEXT, "externalId" TEXT, "category" TEXT, "status" "MonitorStatus" NOT NULL DEFAULT 'ACTIVE', "lastCollectedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Competitor_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Competitor_userId_shopUrl_key" ON "Competitor"("userId","shopUrl"); CREATE INDEX "Competitor_userId_status_idx" ON "Competitor"("userId","status");
CREATE TABLE "Shop" ("id" TEXT PRIMARY KEY, "competitorId" TEXT NOT NULL, "externalId" TEXT, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "rating" DECIMAL(3,2), "reviewCount" INTEGER NOT NULL DEFAULT 0, "productCount" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Shop_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE);
CREATE INDEX "Shop_competitorId_idx" ON "Shop"("competitorId");
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY, "competitorId" TEXT NOT NULL, "shopId" TEXT, "externalId" TEXT, "name" TEXT NOT NULL, "description" TEXT, "url" TEXT NOT NULL, "imageUrl" TEXT, "category" TEXT, "currency" TEXT NOT NULL DEFAULT 'BRL', "currentPrice" DECIMAL(12,2) NOT NULL, "originalPrice" DECIMAL(12,2), "rating" DECIMAL(3,2), "reviewCount" INTEGER NOT NULL DEFAULT 0, "availability" "Availability" NOT NULL DEFAULT 'AVAILABLE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Product_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE, CONSTRAINT "Product_shopId_fkey" FOREIGN KEY ("shopId") REFERENCES "Shop"("id") ON DELETE SET NULL);
CREATE INDEX "Product_competitorId_updatedAt_idx" ON "Product"("competitorId","updatedAt");
CREATE TABLE "ProductSnapshot" ("id" TEXT PRIMARY KEY, "productId" TEXT NOT NULL, "price" DECIMAL(12,2) NOT NULL, "originalPrice" DECIMAL(12,2), "rating" DECIMAL(3,2), "reviewCount" INTEGER NOT NULL, "availability" "Availability" NOT NULL, "estimatedSalesMin" INTEGER, "estimatedSalesMax" INTEGER, "estimatedGmvMin" DECIMAL(14,2), "estimatedGmvMax" DECIMAL(14,2), "confidence" "Confidence", "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductSnapshot_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE);
CREATE INDEX "ProductSnapshot_productId_capturedAt_idx" ON "ProductSnapshot"("productId","capturedAt");
CREATE TABLE "PriceHistory" ("id" TEXT PRIMARY KEY, "productId" TEXT NOT NULL, "price" DECIMAL(12,2) NOT NULL, "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PriceHistory_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE); CREATE INDEX "PriceHistory_productId_capturedAt_idx" ON "PriceHistory"("productId","capturedAt");
CREATE TABLE "Creator" ("id" TEXT PRIMARY KEY, "externalId" TEXT, "username" TEXT NOT NULL, "displayName" TEXT NOT NULL, "profileUrl" TEXT NOT NULL, "avatarUrl" TEXT, "followers" INTEGER NOT NULL DEFAULT 0, "following" INTEGER NOT NULL DEFAULT 0, "totalLikes" BIGINT NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "Creator_externalId_key" ON "Creator"("externalId"); CREATE UNIQUE INDEX "Creator_username_key" ON "Creator"("username");
CREATE TABLE "CreatorSnapshot" ("id" TEXT PRIMARY KEY, "creatorId" TEXT NOT NULL, "followers" INTEGER NOT NULL, "averageViews" INTEGER NOT NULL, "averageLikes" INTEGER NOT NULL, "engagementRate" DECIMAL(7,4) NOT NULL, "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CreatorSnapshot_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "Creator"("id") ON DELETE CASCADE); CREATE INDEX "CreatorSnapshot_creatorId_capturedAt_idx" ON "CreatorSnapshot"("creatorId","capturedAt");
CREATE TABLE "Video" ("id" TEXT PRIMARY KEY, "creatorId" TEXT NOT NULL, "competitorId" TEXT NOT NULL, "externalId" TEXT NOT NULL, "url" TEXT NOT NULL, "description" TEXT, "thumbnailUrl" TEXT, "views" BIGINT NOT NULL DEFAULT 0, "likes" BIGINT NOT NULL DEFAULT 0, "comments" INTEGER NOT NULL DEFAULT 0, "shares" INTEGER NOT NULL DEFAULT 0, "publishedAt" TIMESTAMP(3) NOT NULL, "discoveredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Video_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "Creator"("id") ON DELETE CASCADE, CONSTRAINT "Video_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "Video_externalId_key" ON "Video"("externalId"); CREATE INDEX "Video_competitorId_publishedAt_idx" ON "Video"("competitorId","publishedAt");
CREATE TABLE "ProductVideo" ("productId" TEXT NOT NULL, "videoId" TEXT NOT NULL, PRIMARY KEY ("productId","videoId"), CONSTRAINT "ProductVideo_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE, CONSTRAINT "ProductVideo_videoId_fkey" FOREIGN KEY ("videoId") REFERENCES "Video"("id") ON DELETE CASCADE);
CREATE TABLE "CreatorCompetitor" ("creatorId" TEXT NOT NULL, "competitorId" TEXT NOT NULL, "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("creatorId","competitorId"), CONSTRAINT "CreatorCompetitor_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "Creator"("id") ON DELETE CASCADE, CONSTRAINT "CreatorCompetitor_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE);
CREATE TABLE "Live" ("id" TEXT PRIMARY KEY, "competitorId" TEXT NOT NULL, "creatorId" TEXT, "externalId" TEXT NOT NULL, "title" TEXT, "startedAt" TIMESTAMP(3) NOT NULL, "endedAt" TIMESTAMP(3), "duration" INTEGER, "peakViewers" INTEGER, "totalLikes" BIGINT NOT NULL DEFAULT 0, "totalComments" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Live_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE, CONSTRAINT "Live_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "Creator"("id") ON DELETE SET NULL); CREATE UNIQUE INDEX "Live_externalId_key" ON "Live"("externalId");
CREATE TABLE "LiveProduct" ("liveId" TEXT NOT NULL, "productId" TEXT NOT NULL, "firstSeenAt" TIMESTAMP(3) NOT NULL, "lastSeenAt" TIMESTAMP(3), "displayOrder" INTEGER, "exposureSeconds" INTEGER, PRIMARY KEY ("liveId","productId"), CONSTRAINT "LiveProduct_liveId_fkey" FOREIGN KEY ("liveId") REFERENCES "Live"("id") ON DELETE CASCADE, CONSTRAINT "LiveProduct_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE);
CREATE TABLE "Alert" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "competitorId" TEXT, "productId" TEXT, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "severity" "AlertSeverity" NOT NULL DEFAULT 'INFO', "metadata" JSONB, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Alert_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "Alert_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE CASCADE, CONSTRAINT "Alert_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE); CREATE INDEX "Alert_userId_readAt_createdAt_idx" ON "Alert"("userId","readAt","createdAt");
CREATE TABLE "CollectionJob" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "competitorId" TEXT, "type" TEXT NOT NULL, "status" "JobStatus" NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "startedAt" TIMESTAMP(3), "finishedAt" TIMESTAMP(3), "errorMessage" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CollectionJob_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "CollectionJob_competitorId_fkey" FOREIGN KEY ("competitorId") REFERENCES "Competitor"("id") ON DELETE SET NULL); CREATE INDEX "CollectionJob_userId_status_idx" ON "CollectionJob"("userId","status");
